// ===========================================================================
//  List Executions
//  Every execution of the carousel workflow, oldest first. Oldest first
//  matters: if a paper was generated more than once, the newest run is the
//  one whose images are on disk, so it must be the one that writes last.
// ===========================================================================

const s = $('Settings').first().json;
const base = String(s.N8N_API_URL || '').replace(/\/+$/, '');
if (!base || !s.N8N_API_KEY) {
  throw new Error('Set N8N_API_URL and N8N_API_KEY in the Settings node first.');
}

const headers = { 'X-N8N-API-KEY': s.N8N_API_KEY, accept: 'application/json' };

const only = String(s.ONLY_EXECUTION_IDS || '')
  .split(',').map((x) => x.trim()).filter(Boolean);

let list = [];

if (only.length) {
  // Explicit ids: skip the listing entirely, handy for a first trial run.
  list = only.map((id) => ({ id, startedAt: null, status: null }));
} else {
  let cursor;
  do {
    const qs = { limit: 250, includeData: false };
    if (s.SOURCE_WORKFLOW_ID) qs.workflowId = s.SOURCE_WORKFLOW_ID;
    if (cursor) qs.cursor = cursor;

    const res = await this.helpers.httpRequest({
      method: 'GET', url: `${base}/executions`, qs, headers, json: true,
    });

    list.push(...(res.data || []));
    cursor = res.nextCursor;
  } while (cursor);

  const since = s.STARTED_AFTER ? new Date(s.STARTED_AFTER) : null;
  const until = s.STARTED_BEFORE ? new Date(s.STARTED_BEFORE) : null;

  list = list
    .filter((e) => !since || new Date(e.startedAt) >= since)
    .filter((e) => !until || new Date(e.startedAt) <= until)
    .sort((a, b) => new Date(a.startedAt) - new Date(b.startedAt));
}

if (!list.length) {
  throw new Error(
    `No executions matched. Check SOURCE_WORKFLOW_ID (${s.SOURCE_WORKFLOW_ID || 'not set'}) ` +
    `and the date filters. The workflow id is the last part of its editor URL.`
  );
}

if (s.MAX_EXECUTIONS) list = list.slice(0, Number(s.MAX_EXECUTIONS));

return list.map((e) => ({
  json: {
    id: String(e.id),
    startedAt: e.startedAt,
    status: e.status ?? (e.finished ? 'success' : 'unknown'),
    mode: e.mode,
  },
}));

// ===========================================================================
//  CORE  —  streaming reader for one n8n execution payload.
//
//  Why streaming: this workflow's "Render Carousel" node returns every slide
//  as base64 inside its JSON output, and n8n stores every node's output in
//  the execution. One execution of a 200-paper batch is therefore hundreds of
//  megabytes to several gigabytes, most of it image data we do not want.
//  JSON.parse() on that either blows the heap or exceeds V8's max string
//  length. So the payload is streamed to disk and walked byte by byte, and
//  any large string that is not HTML is thrown away as it is read.
// ===========================================================================

const fs = require('fs');

const BIG_BYTES = 65536;      // above this, a string has to prove it is wanted
const CHUNK = 1 << 22;        // 4 MB read buffer

const LT = 60;                // '<'  — HTML we keep, however large

// Base64 alphabet, for spotting image payloads early.
const B64 = new Uint8Array(256);
for (const ch of 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=') {
  B64[ch.charCodeAt(0)] = 1;
}

// ---------------------------------------------------------------------------
//  Byte reader over a file descriptor.
// ---------------------------------------------------------------------------
function makeReader(fd) {
  const buf = Buffer.allocUnsafe(CHUNK);
  let len = 0;
  let pos = 0;
  let eof = false;

  function fill() {
    if (pos < len || eof) return;
    len = fs.readSync(fd, buf, 0, CHUNK, null);
    pos = 0;
    if (len <= 0) { len = 0; eof = true; }
  }

  return {
    peek() { fill(); return pos < len ? buf[pos] : -1; },
    take() { fill(); return pos < len ? buf[pos++] : -1; },
    skip() { fill(); if (pos < len) pos++; },
  };
}

function ws(rd) {
  for (;;) {
    const c = rd.peek();
    if (c === 32 || c === 10 || c === 13 || c === 9) rd.skip();
    else return;
  }
}

// ---------------------------------------------------------------------------
//  String token. Returns the decoded string, or null when the string was
//  discarded for being a large non-HTML blob (i.e. a base64 image).
//  Raw bytes are copied verbatim and decoded once through JSON.parse, so
//  every escape sequence is handled by the engine rather than by hand.
// ---------------------------------------------------------------------------
function readString(rd) {
  rd.skip(); // opening quote
  const parts = [];
  let cur = Buffer.allocUnsafe(8192);
  let n = 0;
  let total = 0;
  let first = -1;
  let drop = false;
  let esc = false;

  for (;;) {
    const c = rd.take();
    if (c === -1) throw new Error('unterminated string in JSON payload');

    if (esc) {
      esc = false;
    } else if (c === 92) {      // backslash
      esc = true;
    } else if (c === 34) {      // closing quote
      break;
    }

    if (first === -1) first = c;
    total++;

    if (drop) continue;

    if (n === cur.length) { parts.push(cur.subarray(0, n)); cur = Buffer.allocUnsafe(1 << 16); n = 0; }
    cur[n++] = c;

    if (total === BIG_BYTES && first !== LT) {
      // Large and not HTML. If it reads as base64 it is a rendered slide;
      // drop it and keep scanning to the closing quote.
      let b64 = true;
      const head = parts.length ? parts[0] : cur;
      const lim = Math.min(64, head.length);
      for (let i = 0; i < lim; i++) if (!B64[head[i]]) { b64 = false; break; }
      if (b64) { drop = true; parts.length = 0; n = 0; }
    }
  }

  if (drop) return null;
  parts.push(cur.subarray(0, n));
  return JSON.parse('"' + Buffer.concat(parts).toString('utf8') + '"');
}

// A string is skipped without being kept at all.
function skipString(rd) {
  rd.skip();
  let esc = false;
  for (;;) {
    const c = rd.take();
    if (c === -1) throw new Error('unterminated string in JSON payload');
    if (esc) esc = false;
    else if (c === 92) esc = true;
    else if (c === 34) return;
  }
}

function readLiteral(rd, discard) {
  const bytes = [];
  for (;;) {
    const c = rd.peek();
    if (c === -1 || c === 44 || c === 125 || c === 93 ||
        c === 32 || c === 10 || c === 13 || c === 9) break;
    rd.skip();
    if (!discard) bytes.push(c);
  }
  if (discard) return undefined;
  return JSON.parse(Buffer.from(bytes).toString('utf8'));
}

// ---------------------------------------------------------------------------
//  Value walker.
//
//  opts.keepNodes  — Set of node names to keep under a "runData" object;
//                    every other node's output is parsed and thrown away.
//  opts.dropTop    — Set of keys to skip at the top level of the document.
//  opts.dataToFile — when set, a top-level "data" key holding a STRING has
//                    its contents unescaped straight to this path instead of
//                    being held in memory (that string is the whole flatted
//                    execution, far past V8's string limit).
// ---------------------------------------------------------------------------
function parseValue(rd, discard, key, depth, opts, isRunData) {
  ws(rd);
  const c = rd.peek();
  if (c === 123) return parseObject(rd, discard, depth, opts, isRunData);
  if (c === 91) return parseArray(rd, discard, depth, opts);
  if (c === 34) {
    if (!discard && depth === 1 && key === 'data' && opts.dataToFile) {
      return { __file: unescapeToFile(rd, opts.dataToFile) };
    }
    if (discard) { skipString(rd); return undefined; }
    return readString(rd);
  }
  return readLiteral(rd, discard);
}

// isRunData: this object is the runData map, so its keys are node names and
// the nodes we do not need are parsed straight past instead of materialised.
function parseObject(rd, discard, depth, opts, isRunData) {
  rd.skip(); // {
  const out = discard ? undefined : {};
  ws(rd);
  if (rd.peek() === 125) { rd.skip(); return out; }
  for (;;) {
    ws(rd);
    const key = readString(rd);
    ws(rd);
    rd.skip(); // :
    let d = discard;
    if (!d && depth === 0 && opts.dropTop && opts.dropTop.has(key)) d = true;
    if (!d && isRunData && opts.keepNodes && !opts.keepNodes.has(key)) d = true;
    const v = parseValue(rd, d, key, depth + 1, opts, key === 'runData');
    if (!d) out[key] = v;
    ws(rd);
    const t = rd.take();
    if (t === 44) continue;
    if (t === 125) return out;
    throw new Error('malformed object in JSON payload');
  }
}

function parseArray(rd, discard, depth, opts) {
  rd.skip(); // [
  const out = discard ? undefined : [];
  ws(rd);
  if (rd.peek() === 93) { rd.skip(); return out; }
  for (;;) {
    const v = parseValue(rd, discard, null, depth + 1, opts, false);
    if (!discard) out.push(v);
    ws(rd);
    const t = rd.take();
    if (t === 44) continue;
    if (t === 93) return out;
    throw new Error('malformed array in JSON payload');
  }
}

// ---------------------------------------------------------------------------
//  Unescape a JSON string token straight into a file, without ever holding it.
// ---------------------------------------------------------------------------
function unescapeToFile(rd, path) {
  rd.skip(); // opening quote
  const out = fs.openSync(path, 'w');
  const buf = Buffer.allocUnsafe(1 << 20);
  let n = 0;

  const flush = () => { if (n) { fs.writeSync(out, buf, 0, n); n = 0; } };
  const put = (byte) => { if (n === buf.length) flush(); buf[n++] = byte; };
  const putStr = (s) => { const b = Buffer.from(s, 'utf8'); for (let i = 0; i < b.length; i++) put(b[i]); };
  const hex4 = () => {
    let v = 0;
    for (let i = 0; i < 4; i++) {
      const c = rd.take();
      const d = c >= 48 && c <= 57 ? c - 48
        : c >= 97 && c <= 102 ? c - 87
        : c >= 65 && c <= 70 ? c - 55
        : -1;
      if (d < 0) throw new Error('bad \\u escape in JSON payload');
      v = v * 16 + d;
    }
    return v;
  };

  try {
    for (;;) {
      const c = rd.take();
      if (c === -1) throw new Error('unterminated string in JSON payload');
      if (c === 34) break;            // closing quote
      if (c !== 92) { put(c); continue; }

      const e = rd.take();
      if (e === 110) put(10);         // \n
      else if (e === 116) put(9);     // \t
      else if (e === 114) put(13);    // \r
      else if (e === 98) put(8);      // \b
      else if (e === 102) put(12);    // \f
      else if (e === 117) {           // \uXXXX
        const a = hex4();
        if (a >= 0xd800 && a <= 0xdbff) {
          // High surrogate: a low surrogate must follow as its own escape.
          if (rd.peek() === 92) {
            rd.skip();
            const u = rd.take();      // 'u'
            if (u !== 117) throw new Error('bad surrogate pair in JSON payload');
            const b = hex4();
            putStr(String.fromCharCode(a, b));
          } else putStr(String.fromCharCode(a));
        } else putStr(String.fromCharCode(a));
      } else put(e);                  // \" \\ \/ and anything else
    }
    flush();
  } finally {
    fs.closeSync(out);
  }
  return path;
}

function parseFile(path, opts) {
  const fd = fs.openSync(path, 'r');
  try {
    return parseValue(makeReader(fd), false, null, 0, opts || {}, false);
  } finally {
    fs.closeSync(fd);
  }
}

// ---------------------------------------------------------------------------
//  flatted — the format n8n stores execution data in. Every property whose
//  value is a string is an index into the flat array; non-strings are literal.
//  Strings we dropped above sit in the array as null, so they resolve to null.
// ---------------------------------------------------------------------------
function unflatten(arr) {
  if (!Array.isArray(arr)) return arr;
  const seen = new Set();
  const revive = (node) => {
    for (const k of Object.keys(node)) {
      const v = node[k];
      if (typeof v !== 'string') continue;
      const t = arr[Number(v)];
      if (t && typeof t === 'object' && !seen.has(t)) { seen.add(t); node[k] = revive(t); }
      else node[k] = t;
    }
    return node;
  };
  const root = arr[0];
  return root && typeof root === 'object' ? revive(root) : root;
}

// ---------------------------------------------------------------------------
//  Pull the three node outputs we need out of a parsed execution.
// ---------------------------------------------------------------------------
const KEEP_NODES = new Set(['Parse Concept', 'Build Carousel HTML', 'Compute Local Path']);

function runDataOf(parsed) {
  let data = parsed && parsed.data;
  if (data && data.__file) {
    data = unflatten(parseFile(data.__file, {}));
  }
  if (typeof data === 'string') data = unflatten(JSON.parse(data));
  const rd = data && data.resultData && data.resultData.runData;
  return rd && typeof rd === 'object' ? rd : {};
}

// Every output item of a node, flattened across all of its loop iterations.
function outputsOf(runData, node) {
  const runs = runData[node];
  if (!Array.isArray(runs)) return [];
  const out = [];
  for (const run of runs) {
    const main = run && run.data && run.data.main;
    const items = Array.isArray(main) && Array.isArray(main[0]) ? main[0] : [];
    for (const it of items) if (it && it.json) out.push(it.json);
  }
  return out;
}

const keyOf = (p) =>
  p && p.drive_file_id ? `${p.drive_file_id}_${p.variant}_${p.post_index}` : null;

const dirOf = (p) => String(p).replace(/[\\/][^\\/]*$/, '');

function extract(runData) {
  const concepts = new Map();
  for (const j of outputsOf(runData, 'Parse Concept')) {
    const k = keyOf(j);
    if (k) concepts.set(k, j);
  }

  const htmls = new Map();
  for (const j of outputsOf(runData, 'Build Carousel HTML')) {
    const k = keyOf(j._parent);
    if (k && typeof j.html === 'string') htmls.set(k, j.html);
  }

  const targets = new Map();
  for (const j of outputsOf(runData, 'Compute Local Path')) {
    const k = keyOf(j._parent);
    if (!k || !j.fullPath) continue;
    let t = targets.get(k);
    if (!t) {
      t = { dir: dirOf(j.fullPath), folderName: j.folderName, fits: (j._parent && j._parent._fits) || [], slides: new Set() };
      targets.set(k, t);
    }
    t.slides.add(j.slide_number);
  }

  return { concepts, htmls, targets };
}

// ---------------------------------------------------------------------------
//  Write one file per post, next to the slides that post produced.
// ---------------------------------------------------------------------------
function writePosts(ex, { concepts, htmls, targets }, opts) {
  // Everything goes into ONE flat folder, so renamed slide folders do not
  // matter: the original folder name is only used to name the files.
  const outDir = opts.outDir;
  fs.mkdirSync(outDir, { recursive: true });
  const safe = (x) => String(x).replace(/[^\w.\-]+/g, '_').slice(0, 180);

  const written = [];
  const keys = new Set([...htmls.keys(), ...concepts.keys()]);
  for (const k of keys) {
    const c = concepts.get(k);
    const t = targets.get(k);
    const html = htmls.get(k);
    const n = (c && c.post_index) || k.split('_').pop();
    const name = safe(`${(t && t.folderName) || k}__post${n}`);

    if (html) fs.writeFileSync(`${outDir}/${name}.html`, html, 'utf8');
    if (c) {
      const concept = Object.assign({
        _recovered: {
          execution_id: ex.id, started_at: ex.startedAt, row_key: k,
          original_folder: t ? t.dir : null, folder_name: t ? t.folderName : null,
          fits: t ? t.fits : [],
        },
      }, c);
      fs.writeFileSync(`${outDir}/${name}.json`, JSON.stringify(concept, null, 2), 'utf8');
    }

    written.push({
      row_key: k,
      file: `${outDir}/${name}.html`,
      folder: t ? t.dir : `(not rendered) ${k}`,
      folder_name: t ? t.folderName : null,
      post_index: n,
      posts_total: c ? c.posts_total : null,
      total_slides: c ? c.total_slides : null,
      slides_on_disk: t ? t.slides.size : 0,
      html: !!html,
      title: c ? c.title : null,
      variant: c ? c.variant : null,
    });
  }
  return { written, missingConcept: [], notRendered: [] };
}

// ===========================================================================
//  n8n GLUE  —  everything above this line is portable JS with no n8n
//  dependencies, so it can be unit-tested outside n8n.
// ===========================================================================

const s = $('Settings').first().json;
const ex = $input.first().json;

const base = String(s.N8N_API_URL || '').replace(/\/+$/, '');
const workDir = String(s.WORK_DIR || '/files/_recovery').replace(/[\\/]+$/, '');
const raw = `${workDir}/exec_${ex.id}.json`;
const inner = `${workDir}/exec_${ex.id}.inner.json`;

fs.mkdirSync(workDir, { recursive: true });

// --- download -------------------------------------------------------------
// Streamed to disk: one execution of a 200-paper batch is hundreds of MB to
// several GB, nearly all of it base64 slide images, and holding that in
// memory would take n8n down.
const url = `${base}/executions/${ex.id}`;
const qs = { includeData: true };
const headers = { 'X-N8N-API-KEY': s.N8N_API_KEY, accept: 'application/json' };

let streamed = true;
try {
  const stream = await this.helpers.httpRequest({
    method: 'GET', url, qs, headers, json: false, encoding: 'stream', timeout: 1800000,
  });
  await new Promise((resolve, reject) => {
    const out = fs.createWriteStream(raw);
    stream.on('error', reject);
    out.on('error', reject);
    out.on('finish', resolve);
    stream.pipe(out);
  });
} catch (err) {
  // Older n8n builds do not stream; fall back to a buffered download.
  streamed = false;
  const body = await this.helpers.httpRequest({
    method: 'GET', url, qs, headers, json: false, encoding: 'arraybuffer', timeout: 1800000,
  });
  fs.writeFileSync(raw, Buffer.isBuffer(body) ? body : Buffer.from(String(body), 'utf8'));
}

const bytes = fs.statSync(raw).size;

// --- read -----------------------------------------------------------------
let result;
try {
  const parsed = parseFile(raw, {
    dropTop: new Set(['workflowData']),
    keepNodes: KEEP_NODES,
    dataToFile: inner,
  });

  const runData = runDataOf(parsed);
  const nodesSeen = Object.keys(runData);

  if (!nodesSeen.length) {
    result = {
      execution_id: ex.id, started_at: ex.startedAt, status: ex.status,
      bytes, streamed, posts_written: 0, written: [], not_rendered: [], missing_concept: [],
      note: 'This execution carries no saved node data (pruned, or saving was off for this run).',
    };
  } else {
    const found = extract(runData);

    if (s.DRY_RUN) {
      // Report what would happen without touching a single folder.
      const written = [];
      for (const [k, t] of found.targets) {
        const c = found.concepts.get(k);
        if (!c) continue;
        written.push({
          row_key: k, folder: t.dir, folder_name: t.folderName, post_index: c.post_index,
          posts_total: c.posts_total, total_slides: c.total_slides,
          slides_on_disk: t.slides.size, html: found.htmls.has(k),
          folder_exists: fs.existsSync(t.dir), title: c.title, variant: c.variant,
        });
      }
      const notRendered = [];
      for (const k of found.concepts.keys()) if (!found.targets.has(k)) notRendered.push(k);
      result = {
        execution_id: ex.id, started_at: ex.startedAt, status: ex.status, bytes, streamed,
        dry_run: true, posts_written: 0, posts_found: written.length,
        written, not_rendered: notRendered, missing_concept: [], nodes_seen: nodesSeen,
      };
    } else {
      const w = writePosts(ex, found, { outDir: String(s.HTML_OUT_DIR || `${workDir}/html`).replace(/[\\/]+$/, '') });
      result = {
        execution_id: ex.id, started_at: ex.startedAt, status: ex.status, bytes, streamed,
        posts_written: w.written.length, posts_found: w.written.length,
        written: w.written, not_rendered: w.notRendered,
        missing_concept: w.missingConcept, nodes_seen: nodesSeen,
      };
    }
  }
} finally {
  if (!s.KEEP_RAW_DOWNLOAD) {
    try { fs.unlinkSync(raw); } catch (e) {}
    try { fs.unlinkSync(inner); } catch (e) {}
  }
}

return [{ json: result }];

// ===========================================================================
//  Write Manifest  —  runs once, after the last execution has been processed.
//  Writes one index of every recovered post and flags the two things worth
//  looking at by hand before editing anything.
// ===========================================================================

const fs = require('fs');

const s = $('Settings').first().json;
const runs = $input.all().map((i) => i.json);

// Newest execution wins per post, matching whichever run left the images on
// disk. The list arrives oldest first, so a later entry overwrites an earlier.
const byRowKey = new Map();
for (const r of runs) {
  for (const w of r.written || []) {
    byRowKey.set(w.row_key, Object.assign({}, w, {
      execution_id: r.execution_id,
      started_at: r.started_at,
    }));
  }
}
const posts = [...byRowKey.values()];

// Folder naming in the source workflow is surname_title_variant_index, with no
// post index, so a paper that produced 2-3 posts wrote them all into ONE
// folder and each post overwrote the previous one's slides. Those folders hold
// a mix: the concept files are all recovered, the images are not.
const byFolder = new Map();
for (const p of posts) {
  if (!byFolder.has(p.folder)) byFolder.set(p.folder, []);
  byFolder.get(p.folder).push(p);
}

const collisions = [];
for (const [folder, ps] of byFolder) {
  if (ps.length < 2) continue;
  const sorted = ps.slice().sort((a, b) => a.post_index - b.post_index);
  collisions.push({
    folder,
    posts: sorted.map((p) => p.post_index),
    slides_per_post: sorted.map((p) => p.total_slides),
    images_on_disk_belong_to_post: sorted[sorted.length - 1].post_index,
    title: sorted[0].title,
    variant: sorted[0].variant,
  });
}

// A post whose concept says 9 slides but whose run only wrote 6 files.
const shortWrites = posts.filter((p) => p.slides_on_disk && p.total_slides &&
  p.slides_on_disk !== p.total_slides);

const summary = {
  generated_at: new Date().toISOString(),
  dry_run: !!s.DRY_RUN,
  executions_processed: runs.length,
  executions_without_data: runs.filter((r) => r.note).map((r) => r.execution_id),
  bytes_downloaded: runs.reduce((a, r) => a + (r.bytes || 0), 0),
  posts_recovered: posts.length,
  html_recovered: posts.filter((p) => p.html).length,
  folders_touched: byFolder.size,
  folders_holding_more_than_one_post: collisions.length,
  posts_with_fewer_images_than_slides: shortWrites.length,
  concepts_never_rendered: runs.flatMap((r) => r.not_rendered || []),
  slides_without_a_concept: runs.flatMap((r) => r.missing_concept || []),
};

const manifestPath = String(s.WORK_DIR || '/files/_recovery').replace(/[\\/]+$/, '') + '/manifest.json';
fs.mkdirSync(manifestPath.replace(/[\\/][^\\/]*$/, ''), { recursive: true });
fs.writeFileSync(manifestPath, JSON.stringify(
  Object.assign({}, summary, { collisions, short_writes: shortWrites, posts }), null, 2), 'utf8');

return [{ json: Object.assign({ manifest: manifestPath }, summary, { collisions }) }];
